INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '4ff9f92e-8f2a-5329-b408-6b4fcb70f8a2', '196ac3a8-8256-57ee-b777-4ab021e3b449',
  'Append a linked list: list1 is appended into list and will be empty afterward. Which is CORRECT?

Lựa chọn:
- ```c
if (list1->head == NULL)
    head = list1->head;
else {
    p = list1->head;
    while (p->next != NULL)
        p = p->link;
    p->next = head;
}
count = list1->count;
list1->count = 0;
list1->head = NULL;
```
- ```c
if (head == NULL)
    head = list1->head;
else {
    p = head;
    while (p->next != NULL)
        p = p->link;
    p->next = list1->head;
}
count += list1->count;
list1->count = 0;
list1->head = NULL;
```
- ```c
if (head == NULL)
    head = list1->head;
else {
    p = head;
    while (p->next != NULL)
        p = p->link;
    p->next = list1->head;
}
count = list1->count;
list1->count = 0;
list1->head = NULL;
```
- ```c
if (list1->head == NULL)
    list1->head = head;
else {
    p = list1->head;
    while (p->next != NULL)
        p = p->link;
    p->next = head;
}
count += list1->count;
list1->count = 0;
list1->head = NULL;
```', 11
);

